css:
.condcomply-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf5;
    background: linear-gradient(165deg, #0b1622 0%, #101f30 55%, #0d1b2a 100%);
    border-radius: 18px;
}

.condcomply-container * {
    box-sizing: border-box;
}

.condcomply-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0a1420 0%, #14304a 55%, #1d4668 100%);
    color: #f1f6fb;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 200, 0.18);
    box-shadow: 0 16px 38px rgba(0, 0, 0, 0.45);
}

.condcomply-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.condcomply-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f4c95d;
    background: rgba(244, 201, 93, 0.12);
    border: 1px solid rgba(244, 201, 93, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.condcomply-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c2d2e3;
}

.condcomply-signals {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.condcomply-signal {
    background: rgba(20, 38, 58, 0.85);
    border: 1px solid rgba(120, 160, 200, 0.16);
    border-left: 4px solid #d9534f;
    border-radius: 12px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.condcomply-signal-num {
    font-size: 1.5rem;
    font-weight: 800;
    color: #f0a35c;
    font-variant-numeric: tabular-nums;
    line-height: 1.1;
}

.condcomply-signal-label {
    font-size: 0.76rem;
    color: #9fb3c8;
    line-height: 1.35;
}

.condcomply-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfd2;
    margin-bottom: 16px;
    padding: 4px;
}

.condcomply-period-counter #currentDay,
.condcomply-period-counter #maxPeriods {
    font-weight: 800;
    color: #f4c95d;
}

.condcomply-round-name {
    background: rgba(244, 201, 93, 0.14);
    color: #f4c95d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.condcomply-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #f0a35c;
    background: rgba(240, 163, 92, 0.12);
    border: 1px solid rgba(240, 163, 92, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.condcomply-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.condcomply-status-card {
    background: rgba(17, 33, 51, 0.9);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(120, 160, 200, 0.14);
    border-top: 4px solid #4a6b8f;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.32);
}

.condcomply-card-risk { border-top-color: #d9534f; }
.condcomply-card-compliance { border-top-color: #3f86c4; }
.condcomply-card-board { border-top-color: #7d6fc0; }
.condcomply-card-culture { border-top-color: #3fae8e; }

.condcomply-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ea4ba;
}

.condcomply-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f1f6fb;
    font-variant-numeric: tabular-nums;
}

.condcomply-card-risk .condcomply-value { color: #ef6b67; }
.condcomply-card-compliance .condcomply-value { color: #5aa1d8; }
.condcomply-card-board .condcomply-value { color: #9d8fe0; }
.condcomply-card-culture .condcomply-value { color: #4fc6a4; }

.condcomply-sublabel {
    font-size: 0.74rem;
    color: #8ea4ba;
    line-height: 1.35;
}

/* Risk is inverted: low is good (green), high is danger (red). */
.condcomply-card-risk.condcomply-risk-good .condcomply-value { color: #4fc6a4; }
.condcomply-card-risk.condcomply-risk-good { border-top-color: #3fae8e; }
.condcomply-card-risk.condcomply-risk-warn .condcomply-value { color: #f0a35c; }
.condcomply-card-risk.condcomply-risk-warn { border-top-color: #f0a35c; }

.condcomply-meters {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-bottom: 18px;
}

.condcomply-meter {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(20, 38, 58, 0.7);
    border: 1px solid rgba(120, 160, 200, 0.16);
    color: #aebfd2;
    padding: 10px 16px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.condcomply-meter #feeDisplay {
    color: #4fc6a4;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.condcomply-meter #exposureDisplay {
    color: #f0a35c;
    font-weight: 800;
}

.condcomply-meter.condcomply-fee-down #feeDisplay { color: #f0a35c; }
.condcomply-meter.condcomply-exposure-bad #exposureDisplay { color: #ef6b67; }
.condcomply-meter.condcomply-exposure-clear #exposureDisplay { color: #4fc6a4; }

.condcomply-briefing {
    display: flex;
    gap: 14px;
    background: rgba(17, 33, 51, 0.92);
    border-left: 5px solid #f4c95d;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.28);
}

.condcomply-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.condcomply-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f4c95d;
    margin-bottom: 6px;
}

.condcomply-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cddcec;
}

.condcomply-briefing-text strong { color: #f0a35c; }
.condcomply-briefing-text em { color: #5aa1d8; font-style: italic; }

.condcomply-controls {
    background: rgba(15, 28, 44, 0.92);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 200, 0.14);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.28);
}

.condcomply-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f1f6fb;
    border-bottom: 2px solid rgba(120, 160, 200, 0.2);
    padding-bottom: 8px;
}

.condcomply-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cddcec;
    margin: 14px 0 6px;
}

.condcomply-container select,
.condcomply-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2f4d6b;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0f2236;
    color: #e7edf5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.condcomply-container select:focus,
.condcomply-container input[type="number"]:focus {
    outline: none;
    border-color: #f4c95d;
    box-shadow: 0 0 0 3px rgba(244, 201, 93, 0.18);
}

.condcomply-container select option {
    background-color: #0f2236;
    color: #e7edf5;
}

.condcomply-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f4c95d;
}

.condcomply-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aebfd2;
    margin-top: 4px;
}

.condcomply-range-readout span:nth-child(2) {
    color: #f4c95d;
    font-weight: 800;
}

.condcomply-hint {
    font-size: 0.8rem;
    color: #8ea4ba;
    margin-top: 6px;
    line-height: 1.45;
    font-style: italic;
}

.condcomply-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.condcomply-container .btn-primary {
    background: linear-gradient(135deg, #1d4668 0%, #2f6ca0 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(13, 36, 58, 0.55);
}

.condcomply-container .btn-primary:hover {
    filter: brightness(1.1);
}

.condcomply-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2f4d6b;
    color: #9fb3c8;
    background: transparent;
}

.condcomply-coach {
    background: linear-gradient(160deg, #160f1f 0%, #1c1430 100%);
    color: #e8e2f4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(157, 143, 224, 0.28);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35);
}

.condcomply-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b9aef0;
    margin-bottom: 8px;
}

.condcomply-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #ded6f1;
}

.condcomply-coach-body strong { color: #f4c95d; }
.condcomply-coach-body em { color: #b9aef0; font-style: italic; }

.condcomply-history,
.condcomply-chart {
    background: rgba(15, 28, 44, 0.92);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 200, 0.14);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.28);
}

.condcomply-history h3,
.condcomply-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f1f6fb;
}

.condcomply-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cddcec;
}

.condcomply-container table#usfHistoryTable th {
    background: rgba(31, 70, 104, 0.45);
    color: #9bd0ee;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(120, 160, 200, 0.28);
}

.condcomply-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(120, 160, 200, 0.12);
    color: #cddcec;
}

.condcomply-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(31, 70, 104, 0.14);
}

.condcomply-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .condcomply-container {
        padding: 14px;
    }
    .condcomply-header h1 {
        font-size: 1.7rem;
    }
    .condcomply-signals {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .condcomply-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .condcomply-meters {
        grid-template-columns: 1fr;
    }
    .condcomply-value {
        font-size: 2.1rem;
    }
    .condcomply-clock {
        margin-left: 0;
    }
    .condcomply-period-counter {
        font-size: 0.88rem;
    }
    .condcomply-meter {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .condcomply-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, condcomply-cm-*) ===== */
.condcomply-cm { color: #d7e2ee; font-family: inherit; }
.condcomply-cm-generic { font-size: 15px; text-align: center; color: #c3d1e0; }
.condcomply-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(120,160,200,0.18); margin-bottom: 16px; }
.condcomply-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #4fc6a4; }
.condcomply-cm-score-max { font-size: 20px; font-weight: 500; color: #8ea4ba; margin-left: 2px; }
.condcomply-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #e7eef6; }
.condcomply-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #8ea4ba; margin-top: 4px; }
.condcomply-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.condcomply-cm-kpi { flex: 1 1 96px; min-width: 96px; background: rgba(120,160,200,0.08); border: 1px solid rgba(120,160,200,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.condcomply-cm-kpi-val { display: block; font-size: 24px; font-weight: 700; color: #e7eef6; }
.condcomply-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #9fb2c6; }
.condcomply-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.condcomply-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.condcomply-cm-chip.is-met { background: rgba(79,198,164,0.16); border-color: rgba(79,198,164,0.45); color: #7fe0c2; }
.condcomply-cm-chip.is-missed { background: rgba(239,107,103,0.14); border-color: rgba(239,107,103,0.42); color: #f2a6a3; }
.condcomply-cm-insights { margin: 0; padding-left: 18px; }
.condcomply-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #c3d1e0; margin-bottom: 7px; }

