(function() {
    'use strict';

    class CultureComplianceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Culture vs. Compliance`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Bank Pertiwi Berhad).
            this.START_RISK = 78;        // misconduct-risk index, rules-only stays ~78
            this.START_COMPLIANCE = 52;  // regulator-trust standing
            this.START_BOARD = 50;       // board confidence
            this.START_CULTURE = 34;     // culture health (41% pressure, 8% speak-up)
            this.UNFLAGGED_TOTAL = 192;  // 210 branches minus the 18 flagged
            this.TRUE_UNFLAGGED_LOW = 20;  // plausible at-risk lower bound across network
            this.TRUE_UNFLAGGED_HIGH = 70; // plausible at-risk upper bound
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    risk: this.START_RISK,           // misconduct-risk index (0-100, lower safer)
                    compliance: this.START_COMPLIANCE,
                    board: this.START_BOARD,
                    culture: this.START_CULTURE,
                    feeGrowth: 28,                   // fee-income growth outlook (%)
                    remediationSet: 0,               // RM M set aside for customers

                    // Sticky run-defining penalty flags (set when an error is committed;
                    // they GATE the top verdict and CAP KPIs — a later good round cannot wash them out).
                    badApplesRun: false,             // diagnosed bad-apples / disciplined only frontline
                    rulesOnlyRun: false,             // controls-only with incentive scheme left intact
                    concealmentBlewUp: false,        // held/delayed disclosure and BNM found it first
                    overCorrectRun: false,           // scrapped incentives wholesale with no redesign
                    sanitizedBrief: false,           // board brief buried the cultural root cause
                    selfReported: false,             // self-reported promptly to BNM
                    incentiveRedesigned: false,      // redesigned incentives toward customer outcomes
                    systemAccountable: false,        // held the system accountable, not just frontline

                    riskHistory: [this.START_RISK],
                    complianceHistory: [this.START_COMPLIANCE],
                    boardHistory: [this.START_BOARD],
                    cultureHistory: [this.START_CULTURE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the concept's COMMON ERRORS — a blind
                // click-through must NOT auto-win: bad-apples read, rules-only mix,
                // keep the league table, hold disclosure, frontline-only, sanitized brief.
                state.decisions = {
                    diagnosis: `badapples`,
                    evidence: `numbers`,
                    speakup: `reassuring`,
                    unflagged: 0,
                    controls: 50,
                    cultureEffort: 20,
                    sequence: `controlsonly`,
                    incentive: `keep`,
                    disclosure: `hold`,
                    accountability: `frontline`,
                    remediation: 0,
                    complication: `deny`,
                    opening: `isolated`,
                    commitment: `sales`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const di = document.getElementById(`diagnosisInput`);
                const ev = document.getElementById(`evidenceInput`);
                const sp = document.getElementById(`speakupInput`);
                const uf = document.getElementById(`unflaggedInput`);
                if (di) decisions.diagnosis = di.value;
                if (ev) decisions.evidence = ev.value;
                if (sp) decisions.speakup = sp.value;
                if (uf) decisions.unflagged = parseInt(uf.value, 10);
                if (!Number.isFinite(decisions.unflagged) || decisions.unflagged < 0 || decisions.unflagged > this.UNFLAGGED_TOTAL) {
                    warn(`warn_unflagged_range`); return false;
                }
            } else if (round === 2) {
                const co = document.getElementById(`controlsInput`);
                const ce = document.getElementById(`cultureEffortInput`);
                const se = document.getElementById(`sequenceInput`);
                if (co) decisions.controls = parseInt(co.value, 10);
                if (ce) decisions.cultureEffort = parseInt(ce.value, 10);
                if (se) decisions.sequence = se.value;
                if (!Number.isFinite(decisions.controls) || decisions.controls < 0 || decisions.controls > 100) {
                    warn(`warn_controls_range`); return false;
                }
                if (!Number.isFinite(decisions.cultureEffort) || decisions.cultureEffort < 0 || decisions.cultureEffort > 100) {
                    warn(`warn_culture_range`); return false;
                }
            } else if (round === 3) {
                const inc = document.getElementById(`incentiveInput`);
                const di = document.getElementById(`disclosureInput`);
                const ac = document.getElementById(`accountabilityInput`);
                const re = document.getElementById(`remediationInput`);
                if (inc) decisions.incentive = inc.value;
                if (di) decisions.disclosure = di.value;
                if (ac) decisions.accountability = ac.value;
                if (re) decisions.remediation = parseFloat(re.value);
                if (!Number.isFinite(decisions.remediation) || decisions.remediation < 0) {
                    warn(`warn_remediation_value`); return false;
                }
            } else if (round === 4) {
                const cm = document.getElementById(`complicationInput`);
                const op = document.getElementById(`openingInput`);
                const co = document.getElementById(`commitmentInput`);
                const cv = document.getElementById(`convictionInput`);
                if (cm) decisions.complication = cm.value;
                if (op) decisions.opening = op.value;
                if (co) decisions.commitment = co.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let riskDelta = 0, complianceDelta = 0, boardDelta = 0, cultureDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: symptom or system? (Common Error 1: bad-apples framing.)
                switch (d.diagnosis) {
                    case `badbarrel`:
                        riskDelta -= 6; boardDelta += 4; cultureDelta += 3; coachKey = `coach_r1_barrel`;
                        break;
                    case `controls`:
                        // Reads it as a control gap, not a culture problem — primes the rules-only trap.
                        riskDelta += 2; boardDelta += 1; coachKey = `coach_r1_controls`;
                        break;
                    case `badapples`:
                        // The headline anti-pattern's root: misdiagnosis. Sticky flag.
                        ds.badApplesRun = true; riskDelta += 6; cultureDelta -= 4; coachKey = `coach_r1_badapples`;
                        break;
                }

                switch (d.evidence) {
                    case `leaguelink`: riskDelta -= 4; boardDelta += 2; coachKey = (d.diagnosis === `badbarrel`) ? `coach_r1_sharp` : coachKey; break;
                    case `numbers`: riskDelta += 3; coachKey = (coachKey === `coach_default`) ? `coach_r1_numbers` : coachKey; break;
                    case `cancellations`: riskDelta += 2; break;
                }

                switch (d.speakup) {
                    case `redflag`: cultureDelta += 4; riskDelta -= 3; boardDelta += 1; break;
                    case `reassuring`: cultureDelta -= 3; riskDelta += 4; coachKey = (coachKey === `coach_default` || coachKey === `coach_r1_numbers`) ? `coach_r1_speakup` : coachKey; break;
                    case `hrmatter`: cultureDelta -= 2; riskDelta += 2; break;
                }

                // Estimate of unflagged-branch exposure: a credible non-trivial estimate
                // signals a bad-barrel read; "0" denies the systemic spread.
                if (d.unflagged >= this.TRUE_UNFLAGGED_LOW && d.unflagged <= this.TRUE_UNFLAGGED_HIGH) {
                    riskDelta -= 3; boardDelta += 2;
                } else if (d.unflagged === 0) {
                    riskDelta += 4; ds.badApplesRun = true; if (coachKey === `coach_default`) coachKey = `coach_r1_zero`;
                } else if (d.unflagged > this.TRUE_UNFLAGGED_HIGH) {
                    boardDelta -= 1; // over-large estimate, slightly alarms the board
                }

                summaryKey = (d.diagnosis === `badbarrel` && d.evidence === `leaguelink` && d.speakup === `redflag`) ? `sum_r1_good` :
                             (d.diagnosis === `badapples` ? `sum_r1_badapples` : `sum_r1_weak`);
            } else if (round === 2) {
                // Plan: the culture-vs-controls response (Common Error 2: rules-only).
                const controls = d.controls / 100;
                const culture = d.cultureEffort / 100;

                // Controls reduce near-term risk and lift compliance, but on their own do not
                // touch the cause — and resentment if over-applied without culture.
                riskDelta -= 10 * controls;
                complianceDelta += 8 * controls;
                if (controls >= 0.6 && culture <= 0.25) {
                    cultureDelta -= 3; // heavy monitoring, no culture = resented, gamed
                }

                // Culture work is the lever that actually lowers the structural risk.
                riskDelta -= 14 * culture;
                cultureDelta += 16 * culture;
                boardDelta += 4 * culture;

                switch (d.sequence) {
                    case `both`:
                        // The modelled answer: sequence both.
                        riskDelta -= 6; complianceDelta += 4; cultureDelta += 4; boardDelta += 3;
                        coachKey = (culture >= 0.4 && controls >= 0.4) ? `coach_r2_both` : `coach_r2_bothlight`;
                        break;
                    case `controlsonly`:
                        // RULES-ONLY: the sticky flag that floors the misconduct-risk index.
                        ds.rulesOnlyRun = true;
                        complianceDelta += 3; cultureDelta -= 5; coachKey = `coach_r2_controlsonly`;
                        break;
                    case `cultureonly`:
                        // Culture without immediate controls leaves the bleeding unstopped.
                        cultureDelta += 3; complianceDelta -= 4; riskDelta += 3; coachKey = `coach_r2_cultureonly`;
                        break;
                }

                // Choosing the rules-only sequence while neglecting culture compounds the trap.
                if (d.sequence === `controlsonly` && culture < 0.3) {
                    coachKey = `coach_r2_rulesonly_trap`;
                }

                summaryKey = (d.sequence === `both` && culture >= 0.4) ? `sum_r2_good` :
                             (d.sequence === `controlsonly` ? `sum_r2_rulesonly` :
                             (d.sequence === `cultureonly` ? `sum_r2_cultureonly` : `sum_r2_weak`));
            } else if (round === 3) {
                // Decide: intervention mix and disclosure (the core round).
                // (a) The incentive scheme — the smoking gun.
                switch (d.incentive) {
                    case `redesign`:
                        ds.incentiveRedesigned = true;
                        riskDelta -= 14; cultureDelta += 12; boardDelta += 4; ds.feeGrowth = Math.max(0, ds.feeGrowth - 3);
                        coachKey = `coach_r3_redesign`;
                        break;
                    case `scrap`:
                        // Over-correction (Common Error 3): risk drops but morale & growth hit, no redesign.
                        ds.overCorrectRun = true;
                        riskDelta -= 8; cultureDelta -= 4; boardDelta -= 2; ds.feeGrowth = Math.max(0, ds.feeGrowth - 9);
                        coachKey = `coach_r3_scrap`;
                        break;
                    case `keep`:
                        // Keeping the league table guarantees recurrence — the rules-only condition.
                        ds.rulesOnlyRun = true;
                        riskDelta += 8; cultureDelta -= 6; coachKey = `coach_r3_keep`;
                        break;
                }

                // (b) Disclosure to BNM.
                switch (d.disclosure) {
                    case `selfreport`:
                        ds.selfReported = true;
                        complianceDelta += 16; boardDelta += 6; coachKey = (d.incentive === `redesign`) ? `coach_r3_selfreport` : coachKey;
                        break;
                    case `investigate`:
                        // Delay — partial credit but exposes to independent discovery.
                        complianceDelta -= 4; boardDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_investigate`;
                        break;
                    case `hold`:
                        // CONCEALMENT: catastrophic when BNM discovers independently. Sticky flag.
                        ds.concealmentBlewUp = true;
                        complianceDelta -= 22; boardDelta -= 14; riskDelta += 4; coachKey = `coach_r3_hold`;
                        break;
                }

                // (c) Consequence management.
                switch (d.accountability) {
                    case `system`:
                        ds.systemAccountable = true;
                        cultureDelta += 8; boardDelta += 4; riskDelta -= 5;
                        break;
                    case `frontline`:
                        // Bad-apples in action — fire the sellers, leave the system. Sticky flag.
                        ds.badApplesRun = true;
                        cultureDelta -= 6; riskDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r3_frontline` : coachKey;
                        break;
                    case `none`:
                        boardDelta -= 2; cultureDelta -= 1; break;
                }

                // (d) Customer remediation.
                ds.remediationSet = d.remediation;
                if (d.remediation >= 18) { complianceDelta += 6; boardDelta += 3; }
                else if (d.remediation <= 0) { complianceDelta -= 6; boardDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r3_norem`; }

                summaryKey = (d.incentive === `redesign` && d.disclosure === `selfreport` && d.accountability === `system`) ? `sum_r3_good` :
                             (d.disclosure === `hold` ? `sum_r3_conceal` :
                             (d.incentive === `keep` ? `sum_r3_keep` :
                             (d.incentive === `scrap` ? `sum_r3_scrap` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Recover & brief the board under scrutiny.
                switch (d.complication) {
                    case `getahead`:
                        complianceDelta += 8; boardDelta += 8; riskDelta -= 3;
                        // If they had held disclosure, getting ahead now limits but cannot undo the discovery damage.
                        coachKey = `coach_r4_getahead`;
                        break;
                    case `delay`:
                        complianceDelta -= 8; boardDelta -= 8; coachKey = `coach_r4_delay`;
                        if (!ds.selfReported) ds.concealmentBlewUp = true;
                        break;
                    case `deny`:
                        complianceDelta -= 14; boardDelta -= 12; coachKey = `coach_r4_deny`;
                        ds.concealmentBlewUp = true;
                        break;
                }

                switch (d.opening) {
                    case `rootcause`:
                        boardDelta += 12; cultureDelta += 6; coachKey = (d.complication === `getahead`) ? `coach_r4_rootcause` : coachKey;
                        break;
                    case `isolated`:
                        // Sanitized brief (Common Error 5): buries the root cause. Sticky flag.
                        ds.sanitizedBrief = true;
                        boardDelta -= 10; cultureDelta -= 3; coachKey = `coach_r4_isolated`;
                        break;
                    case `competition`:
                        // Lets the 'healthy competition' framing win. Sticky flag.
                        ds.sanitizedBrief = true;
                        boardDelta -= 8; cultureDelta -= 4; riskDelta += 3; coachKey = `coach_r4_competition`;
                        break;
                }

                switch (d.commitment) {
                    case `culture`:
                        cultureDelta += 8; boardDelta += 5; riskDelta -= 4; break;
                    case `reports`:
                        cultureDelta += 1; boardDelta += 1; break;
                    case `sales`:
                        cultureDelta -= 4; riskDelta += 4; boardDelta -= 2;
                        if (coachKey === `coach_default`) coachKey = `coach_r4_sales`;
                        break;
                }

                if (d.conviction >= 60) { cultureDelta += 3; boardDelta += 2; }
                else if (d.conviction <= 25) { cultureDelta -= 2; boardDelta -= 2; }

                summaryKey = (d.complication === `getahead` && d.opening === `rootcause` && d.commitment === `culture`) ? `sum_r4_good` :
                             (d.opening === `isolated` || d.opening === `competition` ? `sum_r4_sanitized` :
                             (d.complication === `deny` ? `sum_r4_deny` : `sum_r4_weak`));
            }

            // ---- Apply deltas (clamped 0-100). ----
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));
            ds.compliance = Math.max(0, Math.min(100, Math.round(ds.compliance + complianceDelta)));
            ds.board = Math.max(0, Math.min(100, Math.round(ds.board + boardDelta)));
            ds.culture = Math.max(0, Math.min(100, Math.round(ds.culture + cultureDelta)));

            // ---- Sticky penalty GATES (caps that a later good round cannot wash out). ----
            // Rules-only / kept-incentive: misconduct risk cannot fall below ~78 (concept benchmark).
            if (ds.rulesOnlyRun && !ds.incentiveRedesigned) {
                ds.risk = Math.max(ds.risk, 72);
                ds.culture = Math.min(ds.culture, 48);
            }
            // Bad-apples: culture health is capped — the barrel is still rotten.
            if (ds.badApplesRun && !ds.systemAccountable) {
                ds.culture = Math.min(ds.culture, 45);
                ds.risk = Math.max(ds.risk, 60);
            }
            // Concealment that blew up: compliance and board confidence collapse.
            if (ds.concealmentBlewUp) {
                ds.compliance = Math.min(ds.compliance, 30);
                ds.board = Math.min(ds.board, 32);
            }
            // Sanitized board brief: board confidence capped (board made complicit).
            if (ds.sanitizedBrief) {
                ds.board = Math.min(ds.board, 48);
            }
            // Over-correction: fee-growth outlook capped low (no redesign, growth sacrificed).
            if (ds.overCorrectRun && !ds.incentiveRedesigned) {
                ds.feeGrowth = Math.min(ds.feeGrowth, 19);
            }

            ds.riskHistory.push(ds.risk);
            ds.complianceHistory.push(ds.compliance);
            ds.boardHistory.push(ds.board);
            ds.cultureHistory.push(ds.culture);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                compliance: ds.compliance,
                complianceDelta: Math.round(complianceDelta),
                board: ds.board,
                boardDelta: Math.round(boardDelta),
                culture: ds.culture,
                cultureDelta: Math.round(cultureDelta),
                feeGrowth: ds.feeGrowth,
                concealmentBlewUp: ds.concealmentBlewUp,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _riskLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`risk_high`);
            if (v >= 40) return t(`risk_mid`);
            return t(`risk_low`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.condcomply-card-risk`);
                if (card) {
                    card.classList.toggle(`condcomply-risk-good`, n < 40);
                    card.classList.toggle(`condcomply-risk-warn`, n >= 40 && n < 60);
                }
                return `${n}`;
            });

            uiManager.bind(`complianceDisplay`, `domainState.compliance`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`boardDisplay`, `domainState.board`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`cultureDisplay`, `domainState.culture`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`feeDisplay`, `domainState.feeGrowth`, (v) => {
                const n = Math.round(Number(v));
                const meter = document.querySelector(`.condcomply-meters .condcomply-meter:first-child`);
                if (meter) meter.classList.toggle(`condcomply-fee-down`, n < 22);
                return `+${n}%`;
            });

            uiManager.bind(`exposureDisplay`, `domainState.remediationSet`, (v) => {
                const n = Number(v);
                const t = window.mySimulation.t.bind(window.mySimulation);
                const ds = window.mySimulation.state.domainState;
                const meter = document.querySelector(`.condcomply-meters .condcomply-meter:last-child`);
                if (ds && ds.concealmentBlewUp) {
                    if (meter) { meter.classList.add(`condcomply-exposure-bad`); meter.classList.remove(`condcomply-exposure-clear`); }
                    return t(`exposure_enforcement`);
                }
                if (n >= 18) {
                    if (meter) { meter.classList.add(`condcomply-exposure-clear`); meter.classList.remove(`condcomply-exposure-bad`); }
                    return t(`exposure_provisioned`);
                }
                if (meter) { meter.classList.remove(`condcomply-exposure-clear`); meter.classList.remove(`condcomply-exposure-bad`); }
                return t(`exposure_open`);
            });

            // Controls slider readout.
            const co = document.getElementById(`controlsInput`);
            const coReadout = document.getElementById(`controlsReadout`);
            if (co && coReadout) {
                coReadout.textContent = co.value;
                co.addEventListener(`input`, function() { coReadout.textContent = co.value; });
            }

            // Culture-effort slider readout.
            const ce = document.getElementById(`cultureEffortInput`);
            const ceReadout = document.getElementById(`cultureEffortReadout`);
            if (ce && ceReadout) {
                ceReadout.textContent = ce.value;
                ce.addEventListener(`input`, function() { ceReadout.textContent = ce.value; });
            }
        }

