        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.riskHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                conductTrajectoryChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.riskHistory },
                        { data: ds.complianceHistory },
                        { data: ds.boardHistory },
                        { data: ds.cultureHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, now the single source of truth. Persisted every
            // period (see calculateResults) so the grading/analytics/LTI layer -- which reads
            // domainState.performance.overallScore then top-level score -- gets a real number
            // instead of null (which the server coerces to 0.0).
            const risk = Math.round(ds.risk);
            const compliance = Math.round(ds.compliance);
            const board = Math.round(ds.board);
            const culture = Math.round(ds.culture);
            return Math.round((100 - risk) * 0.30 + compliance * 0.24 + board * 0.22 + culture * 0.24);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const risk = Math.round(ds.risk);
            const compliance = Math.round(ds.compliance);
            const board = Math.round(ds.board);
            const culture = Math.round(ds.culture);

            // Composite: misconduct risk is inverted (100 - risk), then averaged with the rest.
            const composite = this._composite(ds);

            const lowRisk = risk <= 45;
            const compliant = compliance >= 70;
            const boardBacked = board >= 65;
            const healthyCulture = culture >= 60;

            // Sticky-flag gating: the headline anti-patterns cannot reach the top verdict.
            const cleanRun = !ds.badApplesRun && !ds.rulesOnlyRun && !ds.concealmentBlewUp && !ds.sanitizedBrief;

            let performance = `Conduct Failure`, performanceKey = `grade_conduct_failure`;
            if (ds.concealmentBlewUp) {
                performance = `Concealment Catastrophe`; performanceKey = `grade_concealment`;
            } else if (ds.rulesOnlyRun && !ds.incentiveRedesigned) {
                performance = `Rules-Only Trap`; performanceKey = `grade_rulesonly`;
            } else if (ds.badApplesRun && !ds.systemAccountable) {
                performance = `Bad-Apples Trap`; performanceKey = `grade_badapples`;
            } else if (ds.overCorrectRun && !ds.incentiveRedesigned) {
                performance = `Over-Correction`; performanceKey = `grade_overcorrect`;
            } else if (cleanRun && lowRisk && compliant && boardBacked && healthyCulture && composite >= 75) {
                performance = `Culture-Led Recovery`; performanceKey = `grade_recovery`;
            } else if (cleanRun && compliant && (healthyCulture || lowRisk)) {
                performance = `Conduct Contained`; performanceKey = `grade_contained`;
            } else if (composite >= 55) {
                performance = `Mixed Response`; performanceKey = `grade_mixed`;
            }

            const insights = [];
            if (performance === `Culture-Led Recovery`) insights.push(window.mySimulation.t(`insight_recovery`));
            else if (ds.concealmentBlewUp) insights.push(window.mySimulation.t(`insight_concealment`));
            else if (ds.rulesOnlyRun && !ds.incentiveRedesigned) insights.push(window.mySimulation.t(`insight_rulesonly`));
            else if (ds.badApplesRun && !ds.systemAccountable) insights.push(window.mySimulation.t(`insight_badapples`));
            else if (ds.overCorrectRun && !ds.incentiveRedesigned) insights.push(window.mySimulation.t(`insight_overcorrect`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.sanitizedBrief) insights.push(window.mySimulation.t(`insight_sanitized`));
            if (ds.selfReported && !ds.concealmentBlewUp) insights.push(window.mySimulation.t(`insight_selfreport`));
            if (ds.incentiveRedesigned) insights.push(window.mySimulation.t(`insight_redesign`));
            if (!healthyCulture) insights.push(window.mySimulation.t(`insight_culture_low`));

            return {
                risk: risk,
                compliance: compliance,
                board: board,
                culture: culture,
                lowRisk: lowRisk,
                compliant: compliant,
                boardBacked: boardBacked,
                healthyCulture: healthyCulture,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="condcomply-cm"><p class="condcomply-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, val) =>
                `<div class="condcomply-cm-kpi"><span class="condcomply-cm-kpi-val">${Math.round(val)}</span>`
                + `<span class="condcomply-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="condcomply-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="condcomply-cm">`
                +   `<div class="condcomply-cm-scoreband">`
                +     `<div class="condcomply-cm-score">${summary.composite}<span class="condcomply-cm-score-max">/100</span></div>`
                +     `<div class="condcomply-cm-tier">${tier}</div>`
                +     `<div class="condcomply-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="condcomply-cm-kpis">`
                +     kpi(`cm_kpi_risk`, summary.risk)
                +     kpi(`cm_kpi_compliance`, summary.compliance)
                +     kpi(`cm_kpi_board`, summary.board)
                +     kpi(`cm_kpi_culture`, summary.culture)
                +   `</div>`
                +   `<div class="condcomply-cm-chips">`
                +     chip(summary.lowRisk, `cm_chip_lowrisk`)
                +     chip(summary.compliant, `cm_chip_compliant`)
                +     chip(summary.boardBacked, `cm_chip_board`)
                +     chip(summary.healthyCulture, `cm_chip_culture`)
                +   `</div>`
                +   (insights ? `<ul class="condcomply-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.concealmentBlewUp) return window.mySimulation.t(`hint_concealment`);
            if (ds.rulesOnlyRun && !ds.incentiveRedesigned && state.currentPeriod >= 2) return window.mySimulation.t(`hint_rulesonly`);
            if (ds.badApplesRun && !ds.systemAccountable && state.currentPeriod >= 1) return window.mySimulation.t(`hint_badapples`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (ds.culture < 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_culture`);
            if (ds.risk <= 45 && ds.compliance >= 70 && ds.culture >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.risk`, label: `Risk`, i18nKey: `col_risk`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.compliance`, label: `Compliance`, i18nKey: `col_compliance`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.board`, label: `Board`, i18nKey: `col_board`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.culture`, label: `Culture`, i18nKey: `col_culture`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

